import { PAGINATION_MAX_VISIBLE_PAGES } from "./pagination.constants";
import { PaginationItem } from "./pagination.interface";

export function getPaginationItems(page: number, totalPages: number): PaginationItem[] {
  if (!totalPages) {
    return [];
  }

  if (totalPages <= PAGINATION_MAX_VISIBLE_PAGES) {
    return Array.from({ length: totalPages }, (_, index) => ({
      type: "page" as const,
      page: index + 1,
    }));
  }

  if (page <= 4) {
    return [
      { type: "page", page: 1 },
      { type: "page", page: 2 },
      { type: "page", page: 3 },
      { type: "page", page: 4 },
      { type: "page", page: 5 },
      { type: "ellipsis" },
      { type: "page", page: totalPages },
    ];
  }

  if (page >= totalPages - 3) {
    return [
      { type: "page", page: 1 },
      { type: "ellipsis" },
      { type: "page", page: totalPages - 4 },
      { type: "page", page: totalPages - 3 },
      { type: "page", page: totalPages - 2 },
      { type: "page", page: totalPages - 1 },
      { type: "page", page: totalPages },
    ];
  }

  return [
    { type: "page", page: 1 },
    { type: "ellipsis" },
    { type: "page", page: page - 1 },
    { type: "page", page },
    { type: "page", page: page + 1 },
    { type: "ellipsis" },
    { type: "page", page: totalPages },
  ];
}
